### Building Reusable, Consistent UI

A design system is a collection of reusable components + design tokens (colors, spacing, typography) that enforce visual and behavioral consistency across your product.

#### Design Tokens

```css
/* tokens.css */
:root {
  /* Primitives */
  --color-blue-50: #eff6ff;
  --color-blue-500: #3b82f6;
  --color-blue-900: #1e3a8a;

  --space-1: 4px;
  --space-2: 8px;
  --space-4: 16px;
  --space-8: 32px;

  /* Semantic (reference primitives) */
  --color-interactive: var(--color-blue-500);
  --color-interactive-hover: var(--color-blue-900);
  --space-component-padding: var(--space-4);
}
```

#### Compound Components Pattern

```jsx
// Usage API that's clear and flexible:
<Select>
  <Select.Trigger>Choose a country</Select.Trigger>
  <Select.Content>
    <Select.Item value="us">United States</Select.Item>
    <Select.Item value="uk">United Kingdom</Select.Item>
    <Select.Item value="ca">Canada</Select.Item>
  </Select.Content>
</Select>

// Implementation using Context
const SelectContext = createContext(null);

function Select({ children }) {
  const [isOpen, setIsOpen] = useState(false);
  const [value, setValue] = useState(null);
  return (
    <SelectContext.Provider value={{ isOpen, setIsOpen, value, setValue }}>
      <div className="select">{children}</div>
    </SelectContext.Provider>
  );
}

Select.Trigger = function Trigger({ children }) {
  const { isOpen, setIsOpen } = useContext(SelectContext);
  return <button onClick={() => setIsOpen(!isOpen)}>{children}</button>;
};
```

