### Building for Everyone

Accessibility (a11y) ensures your app is usable by people with disabilities. It also improves SEO and is often legally required.

#### ARIA Roles and Attributes

```jsx
// Buttons: use <button>, not <div onClick>
<div onClick={submit}>Submit</div>  // BAD
<button onClick={submit}>Submit</button>  // GOOD

// Dialogs
<div
  role="dialog"
  aria-modal="true"
  aria-labelledby="dialog-title"
  aria-describedby="dialog-description"
>
  <h2 id="dialog-title">Confirm Action</h2>
  <p id="dialog-description">Are you sure you want to delete?</p>
  <button aria-label="Close dialog" onClick={close}>×</button>
</div>

// Live regions: announce dynamic updates to screen readers
<div
  role="status"
  aria-live="polite"
  aria-atomic="true"
>
  {notification}
</div>

// Form labels
<label htmlFor="email-input">Email address</label>
<input id="email-input" type="email" aria-required="true" />
```

#### Keyboard Navigation

```jsx
// Ensure all interactive elements are focusable
// Tab: moves focus forward
// Shift+Tab: moves focus backward
// Enter/Space: activates buttons
// Escape: closes modals/dropdowns

function Dropdown({ items }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div>
      <button
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onClick={() => setIsOpen(!isOpen)}
        onKeyDown={(e) => {
          if (e.key === 'Escape') setIsOpen(false);
        }}
      >
        Options
      </button>
      {isOpen && (
        <ul role="listbox">
          {items.map(item => (
            <li key={item.id} role="option">{item.label}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

#### Testing Accessibility

```bash
# Automated scanning (catches ~30-40% of issues)
npm install --save-dev axe-core @axe-core/playwright

# In Playwright tests:
const results = await new AxeBuilder({ page }).analyze();
expect(results.violations).toHaveLength(0);
```

